using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using MicroEMR.Web.Models.PatientResults;using MicroEMR.Web.Services.PatientResults;namespace MicroEMR.Web.Controllers;[Authorize]public sealed class PatientResultsController:Controller{private readonly IPatientResultApiClient c;public PatientResultsController(IPatientResultApiClient x)=>c=x;[HttpGet]public async Task<IActionResult>Unreviewed(CancellationToken t=default)=>View(await c.ListUnreviewed(t));[HttpGet]public async Task<IActionResult>List(Guid patientUid,string status="New",CancellationToken t=default)=>Json(new{success=true,results=await c.List(patientUid,status,t)});[HttpGet]public async Task<IActionResult>History(Guid patientUid,Guid resultUid,CancellationToken t=default)=>Json(new{success=true,results=await c.History(patientUid,resultUid,t)});[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(SavePatientResultViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Result information is invalid."});return Json(new{success=true,result=await c.Create(x.PatientUid,x,t)});}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Update(UpdatePatientResultViewModel x,CancellationToken t)=>await Mutation(()=>c.Update(x.PatientUid,x.PatientResultUid,x,t));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Correct(CorrectPatientResultViewModel x,CancellationToken t)=>await Mutation(()=>c.Correct(x.PatientUid,x.PatientResultUid,x,t));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>EnteredInError(EnteredInErrorPatientResultViewModel x,CancellationToken t)=>await Mutation(()=>c.EnteredInError(x.PatientUid,x.PatientResultUid,x,t));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Review(ReviewPatientResultViewModel x,CancellationToken t){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Result review context is invalid. Reload and try again."});try{var result=await c.Review(x.PatientUid,x.PatientResultUid,x,t);return Json(new{success=true,result,message=result?.ReviewWasApplied==true?"Result marked reviewed.":"Result was already reviewed; the original acknowledgement was preserved."});}catch(HttpRequestException e)when(e.StatusCode==System.Net.HttpStatusCode.Conflict){return Conflict(new{success=false,message=e.Message});}}private async Task<IActionResult>Mutation(Func<Task<PatientResultResponse?>> action){if(!ModelState.IsValid)return BadRequest(new{success=false,message="Result information is invalid."});try{return Json(new{success=true,result=await action()});}catch(HttpRequestException e)when(e.StatusCode==System.Net.HttpStatusCode.Conflict){return Conflict(new{success=false,message=e.Message});}}}
